package fetvisuals.gui;

import fetvisuals.FetVisuals; import fetvisuals.module.*; import fetvisuals.module.settings.*; import fetvisuals.render.*; import fetvisuals.theme.Theme;
import net.minecraft.client.gui.DrawContext; import net.minecraft.client.gui.screen.Screen; import net.minecraft.text.Text; import java.util.*;

public final class ClickGuiScreen extends Screen {
    private Category selected=Category.COMBAT; private int scroll; private String search=""; private boolean typing; private final Map<Category,Integer> xs=new EnumMap<>(Category.class); private int dragX,dragY; private boolean dragging;
    public ClickGuiScreen(){super(Text.literal("FetVisuals ClickGUI"));for(Category c:Category.values())xs.put(c,30+c.ordinal()*122);}
    @Override public void render(DrawContext c,int mx,int my,float d){Theme t=FetVisuals.THEMES.current();c.fill(0,0,width,height,0xF0060609);drawSidebar(c,t,mx,my);int x=xs.get(selected),y=30;List<Module> mods=FetVisuals.MODULES.byCategory(selected);RenderUtils.rounded(c,x,y,430,height-60,12,t.panel());FontRenderer.draw(c,selected.name(),x+18,y+15,t.text());FontRenderer.draw(c,"Right Shift  •  close",x+260,y+15,0xFF77727E);int yy=y+46+scroll;for(Module m:mods){if(!search.isEmpty()&&!m.name().toLowerCase().contains(search.toLowerCase()))continue;boolean h=mx>=x+12&&mx<=x+418&&my>=yy&&my<=yy+42;int bg=m.enabled()?RenderUtils.alpha(t.primary(),80):(h?RenderUtils.alpha(t.primary(),30):0x16000000);RenderUtils.rounded(c,x+12,yy,406,40,8,bg);FontRenderer.draw(c,m.name(),x+24,yy+9,t.text());FontRenderer.draw(c,m.description(),x+24,yy+24,0xFF77727E);String state=m.enabled()?"ON":"OFF";FontRenderer.draw(c,state,x+370,yy+13,m.enabled()?t.accent():0xFF5C5962);yy+=48;}}
    private void drawSidebar(DrawContext c,Theme t,int mx,int my){RenderUtils.rounded(c,18,18,104,height-36,12,t.panel());int y=36;for(Category cat:Category.values()){boolean sel=cat==selected;RenderUtils.rounded(c,26,y,88,30,8,sel?RenderUtils.alpha(t.primary(),85):0x00000000);FontRenderer.draw(c,cat.name(),34,y+9,sel?t.text():0xFF7D7884);y+=36;}FontRenderer.draw(c,"SEARCH",34,height-74,0xFF69646F);FontRenderer.draw(c,search.isEmpty()?"type to filter":search,34,height-56,0xFFD0CCD5);}
    @Override public boolean mouseClicked(double mx,double my,int b){if(b!=0)return false;for(Category cat:Category.values()){int y=36+cat.ordinal()*36;if(mx>=26&&mx<=114&&my>=y&&my<=y+30){selected=cat;scroll=0;return true;}}int x=xs.get(selected),y=76+scroll;for(Module m:FetVisuals.MODULES.byCategory(selected)){if(!search.isEmpty()&&!m.name().toLowerCase().contains(search.toLowerCase()))continue;if(my>=y&&my<=y+42&&mx>=x+12&&mx<=x+418){m.toggle();return true;}y+=48;}if(mx>=x&&mx<=x+430&&my<=58){dragging=true;dragX=(int)mx-x;dragY=(int)my-y;return true;}return true;}
    @Override public boolean mouseDragged(double mx,double my,int b,double dx,double dy){if(dragging){xs.put(selected,Math.max(130,(int)mx-dragX));return true;}return false;}
    @Override public boolean mouseReleased(double mx,double my,int b){dragging=false;return true;}
    @Override public boolean mouseScrolled(double mx,double my,double h,double v){scroll+=v>0?24:-24;scroll=Math.min(0,Math.max(scroll,-Math.max(0,FetVisuals.MODULES.byCategory(selected).size()*48-(height-120))));return true;}
    @Override public boolean charTyped(char chr,int mods){if(typing&&search.length()<24&&chr>=32){search+=chr;return true;}return super.charTyped(chr,mods);}
    @Override public boolean keyPressed(int key,int scan,int mods){if(key==256){client.setScreen(null);return true;}if(key==257){typing=!typing;return true;}if(key==259&&!search.isEmpty()){search=search.substring(0,search.length()-1);return true;}return super.keyPressed(key,scan,mods);}
}
